  49             /^The following is [^:]+:?\s*/i,
  50             /^Ok,? (here is|here's) [^:]+:?\s*/i,
  51             /^Below is the [^:]+:?\s*/i,
  52             /^Sure,? I can [^:]+:?\s*/i,
  53         ];
